insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-cred', '{"meaning":"믿다","root":"cred-","words":["credit","credible","incredible","credential","creed"]}'::jsonb, '{"hanja":"信","hun":"믿을 신","words":["신뢰","신용","확신","자신","신념"]}'::jsonb, 3, 'credit ↔ 신용(信用): 금융 용어에서 그대로 대응해요.', null, to_timestamp(1790306000.006)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-duc', '{"meaning":"이끌다","root":"duc- / duct-","words":["produce","educate","induce","conduct","deduce"]}'::jsonb, '{"hanja":"導","hun":"이끌 도","words":["지도","도입","유도","주도","선도"]}'::jsonb, 1, 'induce ↔ 유도(誘導)는 뜻과 구조가 거의 일대일로 대응해요.', null, to_timestamp(1790306000.002)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-fer', '{"meaning":"나르다","root":"fer-","words":["transfer","offer","differ","prefer","confer"]}'::jsonb, '{"hanja":"運","hun":"옮길 운","words":["운반","운송","운영","운명","운용"]}'::jsonb, 4, '뜻이 완전히 같지는 않아요. 차이를 토론해 보세요.', null, to_timestamp(1790306000.008)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-press', '{"meaning":"누르다","root":"press-","words":["express","impress","compress","depress","pressure"]}'::jsonb, '{"hanja":"壓","hun":"누를 압","words":["압박","압축","억압","압도","압력"]}'::jsonb, 2, 'express는 ''밖으로 눌러 짜내다''. 표현(表現)과 비교해 보세요.', null, to_timestamp(1790306000.004)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-spect', '{"meaning":"보다","root":"spect- / spec-","words":["inspect","perspective","respect","spectacle","speculate"]}'::jsonb, '{"hanja":"觀","hun":"볼 관","words":["관점","관찰","객관","낙관","관람"]}'::jsonb, 3, 'respect는 ''다시 돌아보다''에서 존중의 뜻이 됐어요.', null, to_timestamp(1790306000.005)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-spir', '{"meaning":"숨, 숨 쉬다","root":"spir-","words":["inspire","aspire","expire","spirit","conspire"]}'::jsonb, '{"hanja":"氣","hun":"기운 기","words":["활기","사기","용기","분위기","기분"]}'::jsonb, 1, '숨·생기라는 뜻이 통해요. inspire는 ''숨을 불어넣다''에서 왔어요.', null, to_timestamp(1790306000.001)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-ven', '{"meaning":"오다","root":"ven- / vent-","words":["event","invent","prevent","convene","adventure"]}'::jsonb, '{"hanja":"來","hun":"올 래","words":["도래","유래","왕래","미래","내방"]}'::jsonb, 4, 'prevent는 ''앞질러 오다''에서 ''막다''가 됐어요.', null, to_timestamp(1790306000.007)) on conflict (id) do nothing;
insert into public.roots (id, en, ko, session, note, added_by, created_at) values ('root-vert', '{"meaning":"돌리다","root":"vert- / vers-","words":["convert","reverse","diverse","advertise","versatile"]}'::jsonb, '{"hanja":"轉","hun":"구를 전","words":["전환","역전","반전","전향","회전"]}'::jsonb, 2, 'advertise는 라틴어 advertere(주의를 ~쪽으로 돌리다)에서 왔어요.', null, to_timestamp(1790306000.003)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-advertise', 'advertise', '광고하다', '대중의 주의를 ~쪽으로 돌리다 (라틴어 advertere)', '[{"s":"The brand advertises heavily during the holiday season.","t":"그 브랜드는 연말 시즌에 광고를 집중적으로 한다."},{"s":"The position was advertised on several job boards.","t":"그 자리는 여러 구인 사이트에 공고가 났다."},{"s":"They didn''t advertise the price increase.","t":"그들은 가격 인상을 굳이 알리지 않았다."},{"s":"Products advertised as ''natural'' are not always healthier.","t":"''천연''이라고 광고하는 제품이 항상 더 건강한 것은 아니다."}]'::jsonb, '문어', '마케팅·브랜드', 'root-vert', 'en', null, to_timestamp(1790306000.026)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-ascertain', 'ascertain', 'find out → discover → ascertain', '(조사를 통해) 확인하다, 규명하다', '[{"s":"Police are trying to ascertain the cause of the fire.","t":"경찰은 화재 원인을 규명하려 하고 있다."},{"s":"It is difficult to ascertain how many people were affected.","t":"피해자가 몇 명인지 파악하기 어렵다."},{"s":"We need to ascertain whether the contract is still valid.","t":"계약이 아직 유효한지 확인해야 한다."},{"s":"The committee was unable to ascertain the facts.","t":"위원회는 사실관계를 확인하지 못했다."}]'::jsonb, '문어', '일반', null, 'en', null, to_timestamp(1790312000.002)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-bangjeom', '방점을 두다', '중요하게 여기다', 'place emphasis on, prioritize', '[{"s":"인력 운용을 효율화하는 데 방점을 두겠다는 것이다.","t":"The aim is to focus on making workforce management more efficient."},{"s":"이번 개편은 사용자 편의성에 방점을 뒀다.","t":"This redesign puts the emphasis on user convenience."},{"s":"정부 정책의 방점이 성장에서 분배로 옮겨 가고 있다.","t":"The focus of government policy is shifting from growth to distribution."},{"s":"캠페인은 제품 기능보다 브랜드 철학에 방점을 찍었다.","t":"The campaign highlighted the brand''s philosophy rather than product features."}]'::jsonb, '문어', '시사·테크', null, 'ko', null, to_timestamp(1790306000.022)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-boryu', '보류하다', '미루다 → 늦추다 → 보류하다', 'put on hold, shelve', '[{"s":"회사는 신규 투자를 당분간 보류하기로 했다.","t":"The company decided to put new investment on hold for the time being."},{"s":"위원회는 법안 처리를 다음 회기로 보류했다.","t":"The committee deferred the bill to the next session."},{"s":"판단은 추가 자료를 받은 뒤로 보류하겠습니다.","t":"I''ll reserve judgment until we receive further data."},{"s":"출시 일정이 무기한 보류됐다.","t":"The launch has been shelved indefinitely."}]'::jsonb, '문어', '비즈니스·IR', null, 'ko', null, to_timestamp(1790306000.023)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-credible', 'credible', '신빙성 있는, 믿을 만한', '믿을 근거가 있는', '[{"s":"There is no credible evidence to support the claim.","t":"그 주장을 뒷받침할 신빙성 있는 증거는 없다."},{"s":"The company needs a credible plan to reduce its debt.","t":"회사는 부채를 줄일 설득력 있는 계획이 필요하다."},{"s":"Customer reviews make a brand''s promises more credible.","t":"고객 후기는 브랜드의 약속에 신뢰를 더해 준다."},{"s":"Analysts do not see her as a credible challenger.","t":"분석가들은 그녀를 유력한 도전자로 보지 않는다."}]'::jsonb, '문어', '시사·테크', 'root-cred', 'en', null, to_timestamp(1790306000.027)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-ease-pressure', 'ease pressure on', '부담을 완화하다', '~에 가해지는 압박을 덜다', '[{"s":"The project is expected to ease pressure on rents.","t":"이 사업은 임대료 부담을 덜어 줄 것으로 기대된다."},{"s":"The central bank cut rates to ease pressure on households.","t":"중앙은행은 가계 부담을 완화하려고 금리를 내렸다."},{"s":"Hiring two more nurses would ease pressure on the night shift.","t":"간호사 두 명을 더 뽑으면 야간 근무의 부담이 줄어들 것이다."},{"s":"The new bridge should ease pressure on the city''s roads.","t":"새 다리가 시내 도로의 교통 부담을 덜어 줄 것이다."}]'::jsonb, '문어', '시사·테크', 'root-press', 'en', null, to_timestamp(1790306000.029)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-geomto', '검토하다', '알아보다 → 확인하다 → 검토하다', 'review, examine (공식 문서·회의에서)', '[{"s":"관련 부서에서 해당 안건을 검토할 예정입니다.","t":"The relevant department will review the matter."},{"s":"정부는 규제 완화 방안을 적극 검토하고 있다고 밝혔다.","t":"The government said it is actively considering ways to ease regulations."},{"s":"제안서를 면밀히 검토한 뒤 회신드리겠습니다.","t":"We will get back to you after carefully reviewing the proposal."},{"s":"이사회는 매각 여부를 원점에서 재검토하기로 했다.","t":"The board decided to reconsider the sale from scratch."}]'::jsonb, '문어', '비즈니스·IR', null, 'ko', null, to_timestamp(1790306000.02)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-induce', 'induce', '유도하다', '어떤 결과나 행동을 일으키다', '[{"s":"Lower interest rates may induce more borrowing.","t":"금리가 낮아지면 대출이 늘어날 수 있다."},{"s":"The discount was designed to induce first-time buyers to sign up.","t":"그 할인은 첫 구매자의 가입을 유도하려고 기획됐다."},{"s":"Nothing could induce him to change his mind.","t":"어떤 것도 그의 마음을 돌려놓지 못했다."},{"s":"The drug can induce drowsiness in some patients.","t":"이 약은 일부 환자에게 졸음을 유발할 수 있다."}]'::jsonb, '전문', '비즈니스·IR', 'root-duc', 'en', null, to_timestamp(1790306000.025)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-inspire', 'inspire', '영감을 주다, 고무하다', '숨을 불어넣듯 의욕이나 아이디어를 일으키다', '[{"s":"The campaign inspired a new generation of runners.","t":"그 캠페인은 새로운 세대의 러너들에게 영감을 주었다."},{"s":"Her speech inspired employees to rethink how they work.","t":"그녀의 연설은 직원들이 일하는 방식을 다시 생각하게 만들었다."},{"s":"The design was inspired by traditional Korean architecture.","t":"이 디자인은 한국 전통 건축에서 영감을 받았다."},{"s":"Great copy doesn''t just inform; it inspires action.","t":"좋은 카피는 정보를 전달하는 데 그치지 않고 행동을 이끌어 낸다."}]'::jsonb, '문어', '마케팅·브랜드', 'root-spir', 'en', null, to_timestamp(1790306000.024)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-numerous', 'numerous', 'a lot of → many → numerous', '많은, 다수의 (셀 수 있는 명사에만)', '[{"s":"The proposal has received numerous complaints.","t":"그 제안에는 많은 민원이 제기됐다."},{"s":"Numerous studies have linked sleep to memory.","t":"수많은 연구가 수면과 기억의 연관성을 밝혔다."},{"s":"The singer has won numerous awards.","t":"그 가수는 수많은 상을 받았다."},{"s":"On numerous occasions, the board ignored the warnings.","t":"이사회는 여러 차례 경고를 무시했다."}]'::jsonb, '문어', '일반', null, 'en', null, to_timestamp(1790312000.003)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-obtain', 'obtain', 'get → receive → obtain', '(노력이나 절차를 거쳐) 얻다, 취득하다', '[{"s":"Applicants must obtain a visa before entering the country.","t":"신청자는 입국 전에 비자를 발급받아야 한다."},{"s":"The data were obtained from a national survey.","t":"이 자료는 전국 조사에서 얻은 것이다."},{"s":"The company obtained approval from regulators last month.","t":"회사는 지난달 규제 당국의 승인을 받았다."},{"s":"Further information can be obtained from our website.","t":"자세한 내용은 당사 홈페이지에서 확인하실 수 있습니다."}]'::jsonb, '문어', '일반', null, 'en', null, to_timestamp(1790312000.001)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-paak', '파악하다', '알아내다', 'grasp, identify (상황·수치를 정확히 이해하다)', '[{"s":"현황을 정확히 파악하는 것이 우선입니다.","t":"The first priority is to get an accurate picture of the current situation."},{"s":"당국은 아직 사고 원인을 파악하지 못했다.","t":"Authorities have yet to identify the cause of the accident."},{"s":"고객의 요구를 파악해야 설득력 있는 카피가 나온다.","t":"You need to understand what customers want to write persuasive copy."},{"s":"피해 규모는 현재 파악 중이다.","t":"The extent of the damage is still being assessed."}]'::jsonb, '문어', '일반', null, 'ko', null, to_timestamp(1790306000.021)) on conflict (id) do nothing;
insert into public.terms (id, word, pair, meaning, examples, register, domain, root_id, lang, added_by, created_at) values ('t-perspective', 'perspective', '관점, 시각', '사물을 바라보는 위치나 방식', '[{"s":"From a consumer''s perspective, the price is too high.","t":"소비자 입장에서 보면 가격이 너무 높다."},{"s":"Living abroad gave me a new perspective on my own culture.","t":"해외 생활 덕분에 내 문화를 새로운 시각으로 보게 됐다."},{"s":"Let''s put these numbers into perspective.","t":"이 수치를 큰 맥락에서 살펴보자."},{"s":"The report examines the issue from a historical perspective.","t":"보고서는 이 문제를 역사적 관점에서 살펴본다."}]'::jsonb, '문어', '일반', 'root-spect', 'en', null, to_timestamp(1790306000.028)) on conflict (id) do nothing;
insert into public.sessions (id, no, date, dir, title, source, final, notes, created_at) values ('s1-en-kr', 1, null, 'EN→KR', '대역 기사 · 사회 (예시 원문)', 'The city council approved a pilot program that will convert three unused office buildings into affordable housing. Officials said the project is expected to ease pressure on rents in the downtown area, though critics questioned whether the budget would be sufficient to cover renovation costs.', '', '', to_timestamp(1790306000.011)) on conflict (id) do nothing;
insert into public.sessions (id, no, date, dir, title, source, final, notes, created_at) values ('s1-kr-en', 1, null, 'KR→EN', '대역 기사 · 경제 (예시 원문)', '국내 주요 기업들이 올해 하반기 채용 규모를 전년 대비 축소하겠다고 밝혔다. 대외 불확실성이 장기화되면서 신규 투자를 보류하고 인력 운용을 효율화하는 데 방점을 두겠다는 것이다. 전문가들은 청년 고용 여건이 당분간 개선되기 어려울 것으로 내다봤다.', '', '', to_timestamp(1790306000.01)) on conflict (id) do nothing;
